    h, w = len(grid), len(grid[0])

    # Use the recurring vertical stripe pattern to regularize each panel:
    # in odd rows, a panel's pair follows the majority pair in the same row.
    for r in range(h):
        if r % 2 == 0:
            continue
        pairs = []
        for c in range(0, w, 3):
            if c + 1 < w:
                pairs.append(tuple(grid[r][c:c + 2]))
        for i, c in enumerate(range(0, w, 3)):
            if c + 1 >= w:
                continue
            others = pairs[:i] + pairs[i + 1:]
            if others:
                best = max(set(others), key=others.count)
                if others.count(best) >= 2:
                    out[r][c:c + 2] = list(best)
    return out
